import { useState } from 'react';
import { Calendar, Button } from '@jinx-ui/react';

interface ReportDatePickerProps {
  initialDate?: Date;
  onChange?: (date: Date) => void;
}

function startOfDay(date: Date): Date {
  const d = new Date(date);
  d.setHours(0, 0, 0, 0);
  return d;
}

function addDays(date: Date, days: number): Date {
  const d = new Date(date);
  d.setDate(d.getDate() + days);
  return d;
}

const quickOptions: { label: string; getDate: () => Date }[] = [
  { label: 'Сегодня', getDate: () => startOfDay(new Date()) },
  { label: 'Вчера', getDate: () => addDays(startOfDay(new Date()), -1) },
  { label: 'Неделя назад', getDate: () => addDays(startOfDay(new Date()), -7) },
];

export default function ReportDatePicker({ initialDate, onChange }: ReportDatePickerProps) {
  const [selectedDate, setSelectedDate] = useState<Date>(() => startOfDay(initialDate ?? new Date()));

  const handleSelect = (date: Date) => {
    const normalized = startOfDay(date);
    setSelectedDate(normalized);
    onChange?.(normalized);
  };

  return (
    <div
      className="jx-panel"
      style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-3)' }}
    >
      <div
        className="jx-btn-group"
        role="group"
        aria-label="Быстрый выбор даты"
        style={{ display: 'flex', gap: 'var(--jx-space-2)' }}
      >
        {quickOptions.map((option) => {
          const optionDate = option.getDate();
          const isActive = optionDate.getTime() === selectedDate.getTime();
          return (
            <Button
              key={option.label}
              type="button"
              variant={isActive ? 'primary' : 'secondary'}
              size="sm"
              onClick={() => handleSelect(optionDate)}
              aria-pressed={isActive}
            >
              {option.label}
            </Button>
          );
        })}
      </div>
      <Calendar
        mode="single"
        value={selectedDate}
        onChange={handleSelect}
        className="jx-calendar"
      />
    </div>
  );
}

